import{_ as r,c as a,o as t,al as o}from"./chunks/framework.D8UyiDWg.js";const f=JSON.parse('{"title":"MAVLink Microservices (Protocols)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/mavlink/protocols.md","filePath":"zh/mavlink/protocols.md"}'),l={name:"zh/mavlink/protocols.md"};function i(n,e,s,m,c,h){return t(),a("div",null,e[0]||(e[0]=[o('<h1 id="mavlink-microservices-protocols" tabindex="-1">MAVLink Microservices (Protocols) <a class="header-anchor" href="#mavlink-microservices-protocols" aria-label="Permalink to &quot;MAVLink Microservices (Protocols)&quot;">​</a></h1><p>MAVLink &quot;microservices&quot; are a protocols that use multiple messages exchanged between components to communicate more complicated information. For example, the <a href="https://mavlink.io/en/services/command.html" target="_blank" rel="noreferrer">Command Protocol</a> provides an efficient mechanism for packaging a command in a (particular) message and receiving acknowledgement of the command in another message.</p><p>MAVLink microservices are documented the <a href="https://mavlink.io/en/services/" target="_blank" rel="noreferrer">MAVLink Guide</a> (this is not exhaustive: not all messages are grouped into protocols and not all protocols are documented).</p><p>This section lists the services known to be supported/not supported by PX4 in this version.</p><h2 id="supported-microservices" tabindex="-1">Supported Microservices <a class="header-anchor" href="#supported-microservices" aria-label="Permalink to &quot;Supported Microservices&quot;">​</a></h2><p>These services are known to be supported in some form:</p><ul><li><a href="https://mavlink.io/en/services/battery.html" target="_blank" rel="noreferrer">Battery Protocol</a><ul><li><a href="https://mavlink.io/en/messages/common.html#BATTERY_STATUS" target="_blank" rel="noreferrer">BATTERY_STATUS</a> and <a href="https://mavlink.io/en/messages/common.html#BATTERY_STATUS" target="_blank" rel="noreferrer">BATTERY_INFO</a> are streamed.</li></ul></li><li>Camera Protocols <ul><li><a href="https://mavlink.io/en/services/camera.html" target="_blank" rel="noreferrer">Camera Protocol v2</a><ul><li><a href="https://mavlink.io/en/services/camera_def.html" target="_blank" rel="noreferrer">Camera Definition</a></li></ul></li></ul></li><li><a href="https://mavlink.io/en/services/command.html" target="_blank" rel="noreferrer">Command Protocol</a></li><li><a href="https://mavlink.io/en/services/component_information.html" target="_blank" rel="noreferrer">Component Metadata Protocol</a></li><li><a href="https://mavlink.io/en/services/events.html" target="_blank" rel="noreferrer">Events Interface</a></li><li><a href="https://mavlink.io/en/services/ftp.html" target="_blank" rel="noreferrer">File Transfer Protocol (FTP)</a></li><li>Gimbal Protocols <ul><li><a href="https://mavlink.io/en/services/gimbal_v2.html" target="_blank" rel="noreferrer">Gimbal Protocol v2</a><ul><li>Can be enabled by <a href="./../advanced/gimbal_control.html#mavlink-gimbal-mnt-mode-out-mavlink">Gimbal Configuration</a></li><li>PX4 an act as a MAVLink Gimbal for one FC-connected Gimbal</li></ul></li></ul></li><li><a href="https://mavlink.io/en/services/heartbeat.html" target="_blank" rel="noreferrer">Heartbeat/Connection Protocol</a></li><li><a href="https://mavlink.io/en/services/high_latency.html" target="_blank" rel="noreferrer">High Latency Protocol</a> — PX4 streams <a href="https://mavlink.io/en/messages/common.html#HIGH_LATENCY2" target="_blank" rel="noreferrer">HIGH_LATENCY2</a></li><li><a href="https://mavlink.io/en/services/image_transmission.html" target="_blank" rel="noreferrer">Image Transmission Protocol</a></li><li><a href="https://mavlink.io/en/services/landing_target.html" target="_blank" rel="noreferrer">Landing Target Protocol</a></li><li><a href="https://mavlink.io/en/services/manual_control.html" target="_blank" rel="noreferrer">Manual Control (Joystick) Protocol</a></li><li><a href="https://mavlink.io/en/services/mavlink_id_assignment.html" target="_blank" rel="noreferrer">MAVLink Id Assignment (sysid, compid)</a></li><li><a href="https://mavlink.io/en/services/mission.html" target="_blank" rel="noreferrer">Mission Protocol</a></li><li><a href="https://mavlink.io/en/services/offboard_control.html" target="_blank" rel="noreferrer">Offboard Control Protocol</a></li><li><a href="./../peripherals/remote_id.html">Remote ID</a> (<a href="https://mavlink.io/en/services/opendroneid.html" target="_blank" rel="noreferrer">Open Drone ID Protocol</a>)</li><li><a href="https://mavlink.io/en/services/parameter.html" target="_blank" rel="noreferrer">Parameter Protocol</a></li><li><a href="https://mavlink.io/en/services/parameter_ext.html" target="_blank" rel="noreferrer">Parameter Protocol Extended</a> — Allows setting string parameters. Used for setting string parameters set in camera definition files.</li><li><a href="https://mavlink.io/en/services/payload.html" target="_blank" rel="noreferrer">Payload Protocol</a></li><li><a href="https://mavlink.io/en/services/ping.html" target="_blank" rel="noreferrer">Ping Protocol</a></li><li><a href="./../mavlink/standard_modes.html">Standard Modes Protocol</a></li><li><a href="https://mavlink.io/en/services/terrain.html" target="_blank" rel="noreferrer">Terrain Protocol</a></li><li><a href="https://mavlink.io/en/services/timesync.html" target="_blank" rel="noreferrer">Time Synchronization</a></li><li><a href="https://mavlink.io/en/services/traffic_management.html" target="_blank" rel="noreferrer">Traffic Management (UTM/ADS-B)</a></li><li><a href="https://mavlink.io/en/services/arm_authorization.html" target="_blank" rel="noreferrer">Arm Authorization Protocol</a></li></ul><h2 id="unsupported" tabindex="-1">Unsupported <a class="header-anchor" href="#unsupported" aria-label="Permalink to &quot;Unsupported&quot;">​</a></h2><p>These services are not supported/used by PX4:</p><ul><li><a href="https://mavlink.io/en/services/illuminator.html" target="_blank" rel="noreferrer">Illuminator Protocol</a></li><li><a href="https://mavlink.io/en/services/tunnel.html" target="_blank" rel="noreferrer">Tunnel Protocol</a></li></ul>',10)]))}const v=r(l,[["render",i]]);export{f as __pageData,v as default};
